function sendMail(s,from,subject,body,category='info',meta={}){s.emails=s.emails||[];s.emails.unshift({id:uid('mail'),date:s.date,from,subject,body,read:false,category,...meta});s.emails=s.emails.slice(0,300);}
export function markMailRead(state,id){const s=deepClone(state),m=s.emails.find(x=>x.id===id);if(m)m.read=true;return s;}
export function markAllMailRead(state){const s=deepClone(state);s.emails.forEach(m=>m.read=true);return s;}

export function ipSeasonEffect(ip,change){const flexibility=ip.flexibility||50,sweet=clamp(18+flexibility*.25,18,48),noveltyGain=change<=sweet?change*.58:sweet*.58+(change-sweet)*.82,identityPenalty=change<=sweet?Math.max(0,change-sweet*.65)*.08:(change-sweet)*(1.18-flexibility/180),familiarityLoss=Math.max(0,sweet*.45-change)*.09,retainedPopularity=clamp(ip.popularity-identityPenalty-familiarityLoss,0,100),newNovelty=clamp(ip.novelty*.74+noveltyGain-(ip.fatigue||0)*.15,0,100),fatigueChange=change<12?5:change>75?-2:-Math.min(4,change/22);return {retainedPopularity,newNovelty,newFatigue:clamp((ip.fatigue||0)+fatigueChange,0,100),sweet,identityPenalty};}
export function effectiveAppeal(program,ip){const pop=ip?.popularity||8,nov=ip?.novelty||35,fatigue=ip?.fatigue||0,popNov=pop*.52+nov*.28+Math.min(pop,nov)*.20,quality=program.quality||((program.scriptStars||2.5)*16),viewer=program.premiered?(program.viewer||50):quality,critic=program.premiered?(program.critic||50):quality,reception=viewer*.52+critic*.18+quality*.30,marketing=Math.min(15,(program.marketing||0)*.12);return clamp(popNov*.48+reception*.42+(program.momentum||0)*.25-fatigue*.22+marketing,5,100);}
