export function commissionScript(state,form){
  const s=deepClone(state),writer=getEmployee(s,form.writerId);if(!writer||!writer.role.includes('Writer')||form.genre==='Live Sports')return s;
  const episodes=Number(form.episodes),duration=Number(form.duration),speed=writer.skills.speed||65,totalDays=Math.max(episodes,Math.round(episodes*(duration/30)*(8.5-speed/18)*(form.format==='Scripted'?1:form.format==='Reality'?.72:form.format==='News'?.30:form.format==='Live'?.38:form.format==='Contests'?.55:.65))),cost=Math.round(episodes*(duration/30)*(form.format==='Scripted'?13000:form.format==='Reality'?7500:form.format==='Documentaries'?9500:form.format==='Contests'?7000:4500));
  if(s.cash<cost*.25)return s;
  const d={id:uid('dev'),title:form.title?.trim()||`Untitled ${form.genre}`,titleLocked:!!form.title?.trim(),summary:'',format:form.format,genre:form.genre,theme:form.theme||'Contemporary',topic:form.topic||'',angle:form.angle||'Fresh',episodes,duration,writerId:writer.id,status:'Writing',daysRemaining:totalDays,totalDays,elapsedDays:0,episodeInterval:Math.max(1,Math.round(totalDays/episodes)),scriptedEpisodes:0,scripts:[],cost,spent:cost*.25,scriptStars:null,novelty:null,suggestedBudgetPerEpisode:null,target:form.target||affinity(),art:form.art||ART_BY_GENRE[form.genre]||ART_BY_FORMAT[form.format]||'cinematic',font:form.font,p1:form.p1,p2:form.p2,ipId:form.ipId||'new',created:s.date,greenlit:false,refined:false};
  s.developments.push(d);s.cash-=cost*.25;s.totalExpense+=cost*.25;
  sendMail(s,'Development Office',`Writing started: ${d.genre} project`,`${writer.name} has started a ${episodes}-episode, ${duration}-minute ${d.genre} project. A script should become available roughly every ${d.episodeInterval} day${d.episodeInterval===1?'':'s'}; the full season is expected in about ${totalDays} days.`, 'development',{developmentId:d.id});return s;
}
export function rewriteDevelopment(state,id){
  const s=deepClone(state),d=s.developments.find(x=>x.id===id),writer=d&&getEmployee(s,d.writerId);if(!d||d.status!=='Complete'||!writer)return s;const cost=Math.max(12000,d.cost*.18);if(s.cash<cost)return s;
  d.status='Rewrite';d.daysRemaining=7;d.totalDays=7;d.rewriteCount=(d.rewriteCount||0)+1;s.cash-=cost;s.totalExpense+=cost;d.spent+=cost;sendMail(s,'Development Office',`Season rewrite started: ${d.title}`,`${writer.name} will spend one week rewriting the completed season package.`, 'development',{developmentId:d.id});return s;
}
export function refineDevelopment(state,id){
  const s=deepClone(state),d=s.developments.find(x=>x.id===id),writer=d&&getEmployee(s,d.writerId);if(!d||d.status!=='Complete'||d.refined||!writer)return s;const cost=Math.max(10000,Math.round(d.cost*.08));if(s.cash<cost)return s;
  d.status='Refining';d.daysRemaining=7;d.totalDays=7;d.refineCost=cost;s.cash-=cost;s.totalExpense+=cost;d.spent+=cost;sendMail(s,'Development Office',`Season refinement started: ${d.title}`,`${writer.name} is spending seven days polishing continuity, pacing and season-level structure. Production can continue using already-ready scripts.`, 'development',{developmentId:d.id});return s;
}
function developmentDay(s){
  s.developments.forEach(d=>{
    const writer=getEmployee(s,d.writerId);if(!writer)return;
    if(d.status==='Writing'){
      d.elapsedDays=(d.elapsedDays||0)+1;d.daysRemaining=Math.max(0,d.daysRemaining-1);
      const target=d.daysRemaining===0?d.episodes:Math.min(d.episodes,Math.floor(d.elapsedDays/Math.max(1,d.episodeInterval||1)));
      while((d.scriptedEpisodes||0)<target)completeEpisodeScript(s,d,writer,(d.scriptedEpisodes||0)+1);
      if(d.daysRemaining===0){while((d.scriptedEpisodes||0)<d.episodes)completeEpisodeScript(s,d,writer,(d.scriptedEpisodes||0)+1);d.status='Complete';const remaining=Math.max(0,d.cost-(d.spent||0));s.cash-=remaining;s.totalExpense+=remaining;d.spent=(d.spent||0)+remaining;sendMail(s,writer.name,`Season scripts complete: ${d.title}`,`${d.title}\n\n${d.summary}\n\nEpisodes: ${d.episodes}\nDuration: ${d.duration} minutes\nWriter: ${writer.name}\nSeason script rating: ${d.scriptStars.toFixed(1)} / 5 stars\nSuggested episode budget: $${d.suggestedBudgetPerEpisode.toLocaleString()}\n\nYou can proceed immediately or spend one additional week refining the completed season package.`, 'script',{developmentId:d.id});}
    }else if(d.status==='Rewrite'||d.status==='Refining'){
      d.daysRemaining=Math.max(0,d.daysRemaining-1);if(d.daysRemaining>0)return;
      const lift=d.status==='Refining'?clamp(.12+((writer.skills.writing||writer.overall)-60)/180, .08,.42):clamp(.22+((writer.skills.writing||writer.overall)-60)/130,.15,.6);
      d.scripts=(d.scripts||[]).map(sc=>({...sc,stars:Math.round(clamp(sc.stars+lift,1,5)*2)/2,notes:d.status==='Refining'?'Season-refined draft':'Rewritten draft'}));d.scriptStars=avg(d.scripts.map(x=>x.stars));d.refined=d.refined||d.status==='Refining';d.status='Complete';d.suggestedBudgetPerEpisode=suggestedEpisodeBudget(d);syncDevelopmentToProgram(s,d);sendMail(s,writer.name,`${d.refined?'Season refinement':'Rewrite'} complete: ${d.title}`,`Updated season script rating: ${d.scriptStars.toFixed(1)} / 5 stars.`, 'script',{developmentId:d.id,programId:d.programId});
    }
  });
}


export function productionPointBudget(p){return clamp(Math.round(12*((p?.budgetPerEpisode||1)/Math.max(1,p?.suggestedBudgetPerEpisode||p?.baseBudgetPerEpisode||1))),7,20);}
export function availableCastingPool(s,p){const hasCastingDirector=s.employees.some(e=>e.role==='Casting Director'),contracted=s.employees.filter(e=>e.dept==='Talent'),freelance=(s.candidateMarket||[]).filter(e=>e.dept==='Talent'&&(hasCastingDirector||e.overall<=78)).sort((a,b)=>b.overall-a.overall).slice(0,hasCastingDirector?14:6);return [...contracted.map(x=>({...x,source:'Contracted'})),...freelance.map(x=>({...x,source:'Freelance'}))].filter((x,i,a)=>a.findIndex(y=>y.id===x.id)===i);}
