  d.greenlit=true;d.programId=p.id;s.programs.push(p);syncDevelopmentToProgram(s,d);sendMail(s,'Studio Office',`Greenlight approved: ${p.title}`,`${p.title} is now in pre-production. Build the production plan, cast the roles, select a stage and finalize promotion before filming begins.`, 'production',{programId:p.id});return s;
