export function assignCreativeTeam(state,programId,{showrunnerId,directorId}={}){const s=deepClone(state),p=getProgram(s,programId);if(!p)return s;if(showrunnerId)p.team.showrunner=showrunnerId;if(directorId)p.team.director=directorId;return s;}
