export function signNegotiation(state,negotiationId){const s=deepClone(state),n=s.negotiations.find(x=>x.id===negotiationId);if(!n||n.status!=='Agreed')return s;const c=s.candidateMarket.find(x=>x.id===n.candidateId);if(!c)return s;c.salary=n.offerSalary;c.contractYears=n.years;c.backend=n.backend;c.creativeControl=n.creativeControl;c.contractStart=s.date;s.employees.push(c);s.candidateMarket=s.candidateMarket.filter(x=>x.id!==c.id);s.cash-=n.bonus;s.totalExpense+=n.bonus;n.status='Signed';sendMail(s,'HR',`Contract signed: ${c.name}`,`${c.name} officially joins ${s.network.initials} as ${c.role}.`, 'hiring',{employeeId:c.id});return s;}
