export function startRightsAuctionTick(s){s.sports.forEach(x=>{if(x.owned||x.bidEnds<=0)return;x.bidEnds--;if(x.leader===s.network.initials){const r=seeded(`sports-bid-${s.date}-${x.id}`);if(r()>.64){const rival=[...s.competitors].sort((a,b)=>b.strength-a.strength)[Math.floor(r()*4)];x.currentBid=Math.round(x.currentBid*1.08/10000)*10000;x.leader=rival.name;sendMail(s,'Rights Desk',`${x.name}: you have been outbid`,`${rival.name} now leads at $${x.currentBid.toLocaleString()}/year.`, 'rights');}}if(x.bidEnds===0&&x.leader===s.network.initials)awardSport(s,x,x.currentBid||x.cost);});}

export function audienceRankings(s,period='yesterday',scope='national'){
  const scopeKey=scope==='local'?'local':scope==='state'?'state':'national',ownHistory=s.networkAudienceHistory||[],today=dateObj(s.date),start=period==='year'?new Date(today.getFullYear(),0,1):period==='month'?new Date(today.getFullYear(),today.getMonth(),1):new Date(today.getTime()-86400000),ownRows=ownHistory.filter(x=>dateObj(x.date)>=start),ownTotal=ownRows.reduce((a,x)=>a+(x[scopeKey]||0),0),ownAvg=ownTotal/Math.max(1,period==='yesterday'?1:ownRows.length),rows=[{id:'player',name:s.network.name,initials:s.network.initials,scope:'Player',audience:ownAvg,totalAudience:ownTotal,prestige:s.network.prestige,revenue:s.totalRevenue}];
  s.competitors.forEach(c=>{const monthKey=s.date.slice(0,7),monthRow=(c.monthlyAudience||[]).find(x=>x.month===monthKey),daysYear=Math.max(1,Math.floor((today-new Date(today.getFullYear(),0,1))/86400000)+1);let total=period==='yesterday'?c.audience.yesterday:period==='month'?(monthRow?.total||0):c.audience.year,days=period==='yesterday'?1:period==='month'?Math.max(1,monthRow?.days||0):daysYear;if(scope==='state')total*=c.scope==='Local'?.95:c.scope==='State'?1:.08;if(scope==='local')total*=c.scope==='Local'?1:c.scope==='State'?.24:.018;rows.push({id:c.id,name:c.name,scope:c.scope,audience:total/days,totalAudience:total,prestige:c.prestige,revenue:c.revenue});});return rows.sort((a,b)=>b.audience-a.audience);
}
export function currentProgramRankings(s,{scope='national',format='all',band='all'}={}){const rows=[],year=String(new Date(s.date).getFullYear()),scopeKey=scope==='local'?'localAudience':scope==='state'?'stateAudience':'audience',ownMap=new Map();s.ratingsLog.filter(r=>String(r.date||'').startsWith(year)).forEach(r=>{const p=getProgram(s,r.programId);if(!p||format!=='all'&&p.format!==format||band!=='all'&&r.band!==band)return;const x=ownMap.get(p.id)||{programId:p.id,networkId:'player',network:s.network.initials,title:p.title,format:p.format,genre:p.genre,band:r.band,totalAudience:0,n:0,viewer:p.viewer/10,critic:p.critic};x.totalAudience+=r[scopeKey]||0;x.n++;ownMap.set(p.id,x);});rows.push(...ownMap.values().map(x=>({...x,audience:x.totalAudience/Math.max(1,x.n),airings:x.n})));const compMap=new Map();s.competitorRatings.filter(r=>String(r.date||'').startsWith(year)).forEach(r=>{if(format!=='all'&&r.format!==format||band!=='all'&&r.band!==band)return;const key=r.programId,x=compMap.get(key)||{programId:r.programId,networkId:r.networkId,network:s.competitors.find(c=>c.id===r.networkId)?.name||'Rival',title:r.title,format:r.format,genre:r.genre,band:r.band,totalAudience:0,n:0,viewer:r.viewer,critic:r.critic};x.totalAudience+=r[scopeKey]||r.audience;x.n++;compMap.set(key,x);});rows.push(...compMap.values().map(x=>({...x,audience:x.totalAudience/Math.max(1,x.n),airings:x.n})));return rows.sort((a,b)=>b.audience-a.audience);}
export function historicalRecords(s,{format='all',metric='audience'}={}){const all=[...(s.programRecords||[])];const current=currentProgramRankings(s,{format,band:'all'}).map(x=>({...x,year:new Date(s.date).getFullYear()}));const rows=[...all,...current].filter(x=>format==='all'||x.format===format);const key=metric==='viewer'?'viewer':metric==='critic'?'critic':'audience';return rows.sort((a,b)=>(b[key]||0)-(a[key]||0)).slice(0,10);}
function yearEnd(s){const d=dateObj(s.date);if(d.getMonth()===11&&d.getDate()===31&&!s.yearly.recordsProcessed){const year=d.getFullYear(),current=currentProgramRankings(s,{});current.slice(0,150).forEach(x=>s.programRecords.push({...x,year}));s.yearly.recordsProcessed=true;sendMail(s,'Audience Research',`${year} records archived`,'Annual network and program performance has been added to the historical record books.','ratings');}if(d.getMonth()===0&&d.getDate()===1){s.yearly.recordsProcessed=false;s.competitors.forEach(c=>c.audience.year=0);}}

export function runOneDay(s,{silent=false}={}){s.lastDayRevenue=0;s.lastDayAudience=0;developmentDay(s);searchDay(s);negotiationDay(s);facilityDay(s);distributionDay(s);productionDay(s);researchDay(s);dailyOverhead(s);competitorDay(s);airDay(s);licensingDay(s);startRightsAuctionTick(s);yearEnd(s);s.financeLog.push({date:s.date,cash:s.cash,revenue:s.lastDayRevenue,expense:s.lastDayExpense||0});s.financeLog=s.financeLog.slice(-1460);s.date=addDays(s.date,1);if(!silent&&s.cash<0)sendMail(s,'CFO','Cash balance is negative','The network needs financing, rights sales or immediate cost action.','warning');}
export function advanceDays(state,n){const s=deepClone(state);for(let i=0;i<n;i++)runOneDay(s,{silent:true});return s;}
export function alerts(s){const out=[];if(!s.programs.length)out.push({sev:'orange',title:'No programming owned',sub:'License movies or commission an original script.'});if(!s.employees.length)out.push({sev:'orange',title:'No staff',sub:'Open a role search in Organization.'});if(!s.adAgencyContract)out.push({sev:'orange',title:'No advertising agency',sub:'Standard audience currently produces no base ad revenue.'});s.programs.forEach(p=>{if(p.status==='Pre-production'){const c=canStartProduction(s,p);if(!c.ok)out.push({sev:'orange',title:`${p.title}: pre-production blocked`,sub:c.reason})}const runway=Math.floor(p.pipeline.ready-p.pipeline.aired);if(['Production','Ready','On Air'].includes(p.status)&&runway<=1)out.push({sev:'orange',title:`${p.title} runway: ${Math.max(0,runway)}`,sub:'Production/delivery is close to the schedule.'})});if(s.cash<3000000)out.push({sev:'red',title:'Cash reserve dangerously low',sub:'Reduce commitments or improve monetization.'});return out.slice(0,10);}

export function setAdAgency(state,id){return signAdAgency(state,id);}
export function signAd(state){return state;}
export function signAffiliate(state){return state;}
export function expandFacility(state,key){return startFacilityBuild(state,key);}
export function launchStreaming(state){const s=deepClone(state);if(!s.streaming.unlocked||s.streaming.launched||s.cash<3500000)return s;s.cash-=3500000;s.totalExpense+=3500000;s.streaming.launched=true;s.streaming.subscribers=2500;return s;}
export function updateStreaming(state,patch){const s=deepClone(state);Object.assign(s.streaming,patch);return s;}
export function updateNewsroom(state,key,delta){const s=deepClone(state);if(['bureaus','reporters','weather','sportsDesk','investigative'].includes(key)){const cost={bureaus:650000,reporters:140000,weather:280000,sportsDesk:320000,investigative:450000}[key]*delta;if(delta>0&&s.cash<cost)return s;s.newsroom[key]=Math.max(0,s.newsroom[key]+delta);s.cash-=cost;s.totalExpense+=Math.max(0,cost)}return s;}
export function setAutomation(state,key,value){const s=deepClone(state);s.automation[key]=value;return s;}
export function updateNetwork(state,patch){const s=deepClone(state);Object.assign(s.network,patch);if(patch.initials)s.streaming.name=`${patch.initials}+`;return s;}
export function updateProductionPlan(state,programId,focus,technical){const s=deepClone(state),p=getProgram(s,programId);if(p){if(focus)p.productionAllocation={...focus};if(technical)p.technical={...technical}}return s;}
export function rewriteScript(state,programId,episode){const s=deepClone(state),p=getProgram(s,programId),sc=p?.scripts?.find(x=>x.episode===episode);if(sc){const writer=getEmployee(s,p.team.leadWriter),r=seeded(`${s.date}-${p.id}-${episode}-rewrite`)();sc.stars=Math.round(clamp(sc.stars+(writer?.skills.writing||60)/100*.6+(r()-.5)*.5,1,5)*2)/2;p.scriptStars=avg(p.scripts.map(x=>x.stars));}return s;}
export function renewProgram(state,programId,change){const s=deepClone(state),p=getProgram(s,programId),ip=p&&getIP(s,p.ipId),writer=p&&getEmployee(s,p.team?.leadWriter);if(!p||!ip||!writer)return s;if(s.developments.some(d=>d.seasonRenewalFor===p.id&&['Writing','Rewrite','Complete'].includes(d.status)))return s;const e=ipSeasonEffect(ip,Number(change));ip.popularity=e.retainedPopularity;ip.novelty=e.newNovelty;ip.fatigue=e.newFatigue;ip.seasons=(ip.seasons||0)+1;const speed=writer.skills.speed||65,totalDays=Math.max(4,Math.round(p.episodes*(p.duration/30)*(8.5-speed/18)*.72)),cost=Math.round(p.episodes*(p.duration/30)*(p.format==='Scripted'?11000:p.format==='Reality'?6500:4000));if(s.cash<cost*.25)return s;s.cash-=cost*.25;s.totalExpense+=cost*.25;s.developments.push({id:uid('dev'),title:p.title,format:p.format,genre:p.genre,theme:ip.identity?.[1]||'Contemporary',topic:`Season ${p.season+1}`,angle:Number(change)>70?'Experimental':Number(change)<15?'Familiar':'Fresh',episodes:p.episodes,duration:p.duration,writerId:writer.id,status:'Writing',daysRemaining:totalDays,totalDays,cost,spent:cost*.25,scriptStars:null,novelty:null,target:{...p.target},art:p.art,font:p.font,p1:p.p1,p2:p.p2,ipId:ip.id,seasonRenewalFor:p.id,nextSeason:p.season+1,creativeChange:Number(change),created:s.date});return s;}
export function createProgram(state,form){return commissionScript(state,form);}
export function setSchedule(state,day,slot,programId){return scheduleProgram(state,day,slot,programId);}
export function runPromotion(state,programId,type){const s=deepClone(state),p=getProgram(s,programId);if(!p)return s;const options={network:{cost:50000,awareness:3},digital:{cost:80000,awareness:5},press:{cost:120000,awareness:4},premiere:{cost:220000,awareness:6},awards:{cost:350000,awareness:1}},o=options[type];if(!o||s.cash<o.cost)return s;s.cash-=o.cost;s.totalExpense+=o.cost;p.marketingSpend+=o.cost;p.awareness=clamp(p.awareness+o.awareness,0,100);return s;}
export function createLicenseDeal(state,programId){const s=deepClone(state),p=getProgram(s,programId),ip=p&&getIP(s,p.ipId);if(!p||!ip||p.airings<2)return s;const annual=Math.max(80000,(p.viewer*.4+p.critic*.25+ip.popularity*.35)*12000);s.licenses.push({id:uid('lic'),programId:p.id,name:`${p.title} Syndication`,annualRevenue:annual,term:3,status:'Active'});return s;}
export function createMerchDeal(state,ipId,mode='License'){const s=deepClone(state),ip=getIP(s,ipId);if(!ip||ip.fandom<35)return s;let annual=Math.max(50000,(ip.fandom*.5+ip.popularity*.25+(ip.merchPotential||20)*.25)*9000);if(mode==='Direct'){const upfront=450000;if(s.cash<upfront)return s;s.cash-=upfront;s.totalExpense+=upfront;annual*=1.6}s.merchDeals.push({id:uid('merch'),ipId,partner:mode==='Direct'?'Network Consumer Products':'Licensed Consumer Products',mode,baseAnnual:annual,status:'Active'});return s;}
export function programPnL(s,p){const production=(p.productionSpend||0)+(p.residualSpend||0);return {revenue:(p.revenue||0)+(p.licensingRevenue||0)+(p.merchRevenue||0),production,marketing:p.marketingSpend||0,residuals:p.residualSpend||0,contribution:(p.revenue||0)+(p.licensingRevenue||0)+(p.merchRevenue||0)-production-(p.marketingSpend||0)};}
export function createSpinOff(state,ipId,title){const s=deepClone(state),ip=getIP(s,ipId);if(!ip)return s;s.developments.push({id:uid('dev'),title:title||`${ip.name}: After Hours`,format:'Live',genre:'Talk Show',theme:'Contemporary',topic:`Companion to ${ip.name}`,angle:'Familiar',episodes:26,duration:30,writerId:null,status:'Idea',daysRemaining:0,totalDays:0,cost:0,spent:0,scriptStars:null,novelty:null,target:{...ip.affinity},art:'bars',font:'wide',p1:'#9272d1',p2:'#1b213d',ipId});return s;}
